package android.os;
public class RemoteCallbackList<T> { public boolean register(T value){throw new AssertionError();} public boolean unregister(T value){throw new AssertionError();} public int beginBroadcast(){throw new AssertionError();} public T getBroadcastItem(int i){throw new AssertionError();} public void finishBroadcast(){throw new AssertionError();} }
